const M = require('lv-automation').metaAds;
const it = $input.first();
// Raw bytes exactly as received (binary), kept for the byte-for-byte forward to W30 / W31 (I-16, I-25).
const buf = it.binary && it.binary.data ? Buffer.from(it.binary.data.data, 'base64') : Buffer.from(it.json.rawBody || JSON.stringify(it.json.body), 'utf8');
const raw = buf.toString('utf8');
const sig = (it.json.headers || {})['x-hub-signature-256'];
if (!M.verifyWebhookSignature(raw, sig, $env.META_APP_SECRET)) return [{ json: { valid: false } }];
const body = JSON.parse(raw);
const events = M.parseLeadgenWebhook(body);
const out = events.map((e) => ({ json: { valid: true, ...e } }));
// Page object: feed comments -> W30, Messenger DMs -> W31. Forward the ORIGINAL body (base64 of the received bytes) + the
// original signature header; the callee verifies it itself. Nothing is re-serialised, nothing is trusted because W02 checked it.
if (body && body.object === 'page') {
  const entries = Array.isArray(body.entry) ? body.entry : [];
  const hasComment = entries.some((e) => (e.changes || []).some((c) => c && c.field === 'feed' && c.value && c.value.item === 'comment'));
  const hasDm = entries.some((e) => Array.isArray(e.messaging) && e.messaging.length > 0);
  const fwd = (route) => ({ json: { valid: true, route, raw_body_b64: buf.toString('base64'), signature: sig } });
  if (hasComment) out.push(fwd('w30'));
  if (hasDm) out.push(fwd('w31'));
}
if (!out.length) return [{ json: { valid: true, empty: true } }];
return out;

const M = require('lv-automation').metaAds;
const client = M.createClient({ token: $env.META_SYSTEM_USER_TOKEN, apiVersion: $env.META_API_VERSION || 'v23.0', maxInlineWaitMs: 5000 });
const ev = $('Verify signature + parse leadgen events').item.json;
if ($input.item.json.id) return [{ json: { action: 'duplicate', leadgen_id: ev.leadgen_id } }]; // webhook re-delivery
const lead = await client.fetchLead(ev.leadgen_id);
const q = M.qualifyLead(lead);
if (!q.qualified) return [{ json: { action: 'routed_out', leadgen_id: ev.leadgen_id, form_id: lead.form_id, ad_id: lead.ad_id, reasons: q.reasons } }];
// Payload for "W01 Lead core" (same contract as the web path; origin = lead_ad). No raw Meta blobs, no age/budget beyond the bands.
return [{ json: { action: 'ingest', lead: {
  origin: 'lead_ad', leadgen_id: lead.leadgen_id, form_id: lead.form_id, full_name: lead.full_name, mobile_raw: lead.phone, email: lead.email || null,
  campaign_id: lead.campaign_id, adset_id: lead.adset_id, ad_id: lead.ad_id, concept: lead.ad_parts && lead.ad_parts.concept, angle: lead.ad_parts && lead.ad_parts.angle,
  platform: lead.platform, age_band: lead.answers.age_band, budget_band: lead.answers.budget_band, preferred_method_ok: true, bond_children: q.bond_children,
  consent: { given: true, source: 'meta_instant_form', form_id: lead.form_id, text_version: 'CONSENT-NAMED-v1+CONSENT-ADS-v1', raw: lead.consent_raw, captured_at: lead.created_time },
  lead_event_id: 'evt_' + lead.leadgen_id + '_lead', is_synthetic: false } } }];

const q = $json.query || {};
const ok = q['hub.mode'] === 'subscribe' && q['hub.verify_token'] === $env.META_WEBHOOK_VERIFY_TOKEN;
return [{ json: { ok, challenge: ok ? String(q['hub.challenge']) : 'forbidden' } }];
